/**
 * Entry point for the reusable "draft release notes" workflow. Runs
 * alongside consolidate-release on every `v*.*.*` tag push: drafts a
 * user-facing release notes summary from the log entries since the
 * previous release tag, and commits it straight into the vault at
 * projects/<project-name>/releases/<tag>.md — no PR, unlike master docs
 * (Requirement #5). Unlike a master doc, this is pinned to one immutable
 * tag rather than an evolving official record, so there's no ongoing
 * accuracy to protect with human review; it's the same "draft trail, no
 * approval" trust model as a log entry, just scoped to a whole release
 * instead of a single push.
 */
export declare function draftReleaseNotes(): Promise<void>;
